// The Stack Garden mark, generated by recursion.
//
// Concept: "a recursion growing inside a raked-sand circle".
//   - 2–3 thin concentric arcs (raked sand), open like an ensō brush circle,
//     with a small gap at the upper right
//   - inside, a bonsai drawn by a recursive branch(): binary, slightly asymmetric,
//     tapered strokes (trunk thick -> twigs thin)
//   - exactly ONE tip glows in the warm accent ("the note playing now"),
//     every other tip is a tiny cream dot
// Flat: no gradients, no shadows. Pure: returns SVG strings (used by the
// generator script AND rendered inline by the app header / Begin screen).

import { color } from "../visual/tokens"; // relative: also compiled standalone by scripts/generate-logo.ts

export interface LogoTheme {
  ink: string; // tree + dots
  sand: string; // arcs
  accent: string; // the one glowing tip
  ground?: string; // optional background
}

export const DARK_THEME: LogoTheme = { ink: color.paper100, sand: color.sea300, accent: color.lantern400 };
export const LIGHT_THEME: LogoTheme = { ink: color.ink800, sand: color.teal500, accent: "#c98636" /* lantern-400, darkened for 3:1 on paper */ };

export interface MarkOptions {
  size?: number; // viewBox size (square)
  depth?: number; // recursion depth (3 for the mark, 2 for the favicon)
  stroke?: number; // overall stroke weight multiplier
  arcs?: number; // 1–3 sand arcs
  theme?: LogoTheme;
  background?: boolean; // filled rounded square behind (favicon)
}

interface Segment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  w1: number;
  w2: number;
}
interface Tip {
  x: number;
  y: number;
  path: string;
}

const deg = (d: number) => (d * Math.PI) / 180;
const f = (n: number) => Number(n.toFixed(2));

/**
 * The recursion. Every call draws one tapered branch and calls itself twice.
 * Asymmetry: the left child is longer and steeper, the right child shorter and wider.
 */
export function growTree(depth: number, unit: number): { segments: Segment[]; tips: Tip[] } {
  const segments: Segment[] = [];
  const tips: Tip[] = [];

  function branch(x: number, y: number, angle: number, len: number, width: number, d: number, path: string) {
    const x2 = x + Math.sin(angle) * len;
    const y2 = y - Math.cos(angle) * len;
    const w2 = width * 0.64;
    segments.push({ x1: x, y1: y, x2, y2, w1: width, w2 });
    if (d === depth) {
      tips.push({ x: x2, y: y2, path });
      return;
    }
    branch(x2, y2, angle - deg(27 - d * 2), len * 0.76, w2, d + 1, path + "L");
    branch(x2, y2, angle + deg(33 + d * 3), len * 0.66, w2, d + 1, path + "R");
  }

  branch(0, 0, deg(5), unit, unit * 0.2, 0, "");
  return { segments, tips };
}

/** A tapered stroke as a filled path, with round ends (circles joined by tangents). */
function taperPath(s: Segment): string {
  const dx = s.x2 - s.x1;
  const dy = s.y2 - s.y1;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  const a1 = { x: s.x1 + (nx * s.w1) / 2, y: s.y1 + (ny * s.w1) / 2 };
  const b1 = { x: s.x1 - (nx * s.w1) / 2, y: s.y1 - (ny * s.w1) / 2 };
  const a2 = { x: s.x2 + (nx * s.w2) / 2, y: s.y2 + (ny * s.w2) / 2 };
  const b2 = { x: s.x2 - (nx * s.w2) / 2, y: s.y2 - (ny * s.w2) / 2 };
  const r1 = s.w1 / 2;
  const r2 = s.w2 / 2;
  // both caps bulge outward (sweep 0 in SVG's y-down space), so joints stay solid
  return `M${f(a1.x)} ${f(a1.y)}L${f(a2.x)} ${f(a2.y)}A${f(r2)} ${f(r2)} 0 0 0 ${f(b2.x)} ${f(b2.y)}L${f(b1.x)} ${f(b1.y)}A${f(r1)} ${f(r1)} 0 0 0 ${f(a1.x)} ${f(a1.y)}Z`;
}

/** An open arc (ensō) centred on (cx, cy); the gap is centred on `gapAt` degrees (0 = up, clockwise). */
function arcPath(cx: number, cy: number, r: number, gapAt: number, gap: number): string {
  const start = deg(gapAt + gap / 2);
  const end = deg(gapAt - gap / 2 + 360);
  const p = (a: number) => ({ x: cx + Math.sin(a) * r, y: cy - Math.cos(a) * r });
  const s = p(start);
  const e = p(end);
  const large = end - start > Math.PI ? 1 : 0;
  return `M${f(s.x)} ${f(s.y)}A${f(r)} ${f(r)} 0 ${large} 1 ${f(e.x)} ${f(e.y)}`;
}

export interface MarkGeometry {
  svgInner: string;
  tipCount: number;
  glowTip: Tip;
}

/** Build the mark's SVG content (without the <svg> wrapper) in a size×size box. */
export function markInner(opts: MarkOptions = {}): MarkGeometry {
  const size = opts.size ?? 512;
  const depth = opts.depth ?? 3;
  const k = opts.stroke ?? 1;
  const arcs = opts.arcs ?? 3;
  const theme = opts.theme ?? DARK_THEME;
  const c = size / 2;
  const parts: string[] = [];

  if (opts.background) {
    parts.push(`<rect width="${size}" height="${size}" rx="${f(size * 0.22)}" fill="${theme.ground ?? color.ink950}"/>`);
  }

  // raked-sand ensō arcs: outermost is the strongest brush stroke, inner ones lighter
  const arcSpec = [
    { r: 0.44, w: 0.017, gapAt: 40, gap: 30, o: 0.9 },
    { r: 0.385, w: 0.0105, gapAt: 52, gap: 44, o: 0.6 },
    { r: 0.33, w: 0.007, gapAt: 30, gap: 58, o: 0.4 },
  ].slice(0, arcs);
  for (const a of arcSpec) {
    parts.push(
      `<path d="${arcPath(c, c, a.r * size, a.gapAt, a.gap)}" fill="none" stroke="${theme.sand}" stroke-opacity="${a.o}" stroke-width="${f(a.w * size * k)}" stroke-linecap="round"/>`,
    );
  }

  // the recursive bonsai, centred inside the inner circle
  const unit = size * (depth >= 3 ? 0.168 : 0.27);
  const { segments, tips } = growTree(depth, unit);
  const xs = segments.flatMap((s) => [s.x1, s.x2]);
  const ys = segments.flatMap((s) => [s.y1, s.y2]);
  const ox = c - (Math.min(...xs) + Math.max(...xs)) / 2;
  const oy = c - (Math.min(...ys) + Math.max(...ys)) / 2 + size * 0.015;
  const scaled = segments.map((s) => ({ x1: s.x1 + ox, y1: s.y1 + oy, x2: s.x2 + ox, y2: s.y2 + oy, w1: s.w1 * k, w2: s.w2 * k }));
  parts.push(`<path d="${scaled.map(taperPath).join("")}" fill="${theme.ink}"/>`);

  // tips: one glowing accent tip (the highest one on the right), the rest tiny cream dots
  const moved = tips.map((t) => ({ ...t, x: t.x + ox, y: t.y + oy }));
  const glow = moved.filter((t) => t.x > c).sort((a, b) => a.y - b.y)[0] ?? moved[0];
  const dotR = size * 0.011 * k;
  for (const t of moved) {
    if (t === glow) continue;
    parts.push(`<circle cx="${f(t.x)}" cy="${f(t.y)}" r="${f(dotR)}" fill="${theme.ink}"/>`);
  }
  const glowR = Math.max(size * 0.026 * Math.min(k, 1.6), size < 64 ? size * 0.06 : 0);
  if (size >= 64) {
    // a thin halo ring (flat, no blur) only where there is room for it
    parts.push(`<circle cx="${f(glow.x)}" cy="${f(glow.y)}" r="${f(glowR * 1.85)}" fill="none" stroke="${theme.accent}" stroke-opacity="0.45" stroke-width="${f(size * 0.007 * k)}"/>`);
  }
  parts.push(`<circle cx="${f(glow.x)}" cy="${f(glow.y)}" r="${f(glowR)}" fill="${theme.accent}"/>`);

  return { svgInner: parts.join(""), tipCount: tips.length, glowTip: glow };
}

export function markSvg(opts: MarkOptions = {}, title = "Stack Garden"): string {
  const size = opts.size ?? 512;
  const { svgInner } = markInner(opts);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" role="img" aria-label="${title}"><title>${title}</title>${svgInner}</svg>`;
}

/** The 32 px favicon: depth 2, thicker strokes, one arc, on a dark rounded square. */
export const FAVICON_OPTIONS: MarkOptions = { size: 32, depth: 2, stroke: 2.3, arcs: 1, background: true };

/** Optical small size (≈ 40–128 px on screen): same recursion, heavier strokes, two arcs. */
export const SMALL_MARK_OPTIONS: MarkOptions = { size: 512, depth: 3, stroke: 1.75, arcs: 2 };

/** Tiny inline size (header, ≈ 28–36 px): depth 2 like the favicon, no background. */
export const TINY_MARK_OPTIONS: MarkOptions = { size: 64, depth: 2, stroke: 2.1, arcs: 2 };
